// RunStoreSuite applies the checks of Store, and the checks that opts add,
// to a fresh subject of newSubject for each check.
func RunStoreSuite[T store.Store](t *testing.T, newSubject func() T, opts ...StoreOption) {
	t.Helper()
	RunStoreSuiteFromHandle(t, func(*StoreHandle) T { return newSubject() }, opts...)
}

// RunStoreSuiteFromHandle applies the same checks to a subject that
// newSubject builds from the handle of each check.
func RunStoreSuiteFromHandle[T store.Store](t *testing.T, newSubject func(h *StoreHandle) T, opts ...StoreOption) {
	t.Helper()
	conform.Run(t, StoreSuite(), storeSubjects(newSubject), opts...)
}

// FuzzStoreSuite registers on f the fuzz target of the property checks of
// callable, on a subject that newSubject builds from the handle of each
// case.
func FuzzStoreSuite[T store.Store](
	f *testing.F,
	callable conform.Callable[store.Store],
	newSubject func(h *StoreHandle) T,
	opts ...StoreOption,
) {
	f.Helper()
	conform.Fuzz(f, StoreSuite(), callable, storeSubjects(newSubject), opts...)
}

// RunStoreBudgets applies the allocation ceilings of Store and its checks
// that count allocations, and the ceilings and the checks that opts add,
// to a fresh subject of newSubject for each case.
func RunStoreBudgets[T store.Store](t *testing.T, newSubject func(h *StoreHandle) T, opts ...StoreOption) {
	t.Helper()
	conform.RunBudgets(t, StoreSuite(), storeSubjects(newSubject), opts...)
}

// BenchStoreSuite measures callable on a subject of newSubject, under the
// ceilings of its budget.
func BenchStoreSuite[T store.Store](
	b conform.B,
	callable conform.Callable[store.Store],
	newSubject func(h *StoreHandle) T,
	opts ...StoreOption,
) {
	b.Helper()
	conform.Bench(b, StoreSuite(), callable, storeSubjects(newSubject), opts...)
}

// storeSubjects returns the factory of the subjects of Store that calls
// newSubject with the handle of each check.
func storeSubjects[T store.Store](newSubject func(h *StoreHandle) T) func(h *StoreHandle) store.Store {
	return func(h *StoreHandle) store.Store { return newSubject(h) }
}

// storeWriterCalls generates the calls of Store.Writer with the inputs
// that each case draws.
var storeWriterCalls = prop.Composite(func(c *prop.Case) func(context.Context, store.Store) error {
	s := c.Draw(prop.Of[shard.Scope](), "s")
	inc := c.Draw(prop.Of[shard.NamespaceIncarnation](), "inc")
	term := c.Draw(prop.Of[epoch.Epoch](), "term")
	return func(_ context.Context, subject store.Store) error {
		_ = subject.Writer(s, inc, term)
		return nil
	}
})

